import React from 'react';

function EventList({ events, onBook, onRefresh, loading }) {
  if (loading) return <p>Loading events...</p>;

  if (events.length === 0) {
    return <p>No events found. Create one below!</p>;
  }

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2>Available Events</h2>
        <button onClick={onRefresh} style={{ padding: '6px 12px' }}>
          🔄 Refresh
        </button>
      </div>
      <table border="1" cellPadding="8" cellSpacing="0" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead style={{ backgroundColor: '#f0f0f0' }}>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Description</th>
            <th>Date</th>
            <th>Total Seats</th>
            <th>Available Seats</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {events.map((event) => (
            <tr key={event.id}>
              <td>{event.id}</td>
              <td>{event.name}</td>
              <td>{event.description || '-'}</td>
              <td>{new Date(event.date).toLocaleString()}</td>
              <td>{event.total_seats}</td>
              <td>
                <strong style={{ color: event.available_seats === 0 ? 'red' : 'green' }}>
                  {event.available_seats}
                </strong>
              </td>
              <td>
                {event.available_seats === 0 ? (
                  <span style={{ color: 'red' }}>Fully Booked</span>
                ) : (
                  <span style={{ color: 'green' }}>Open</span>
                )}
              </td>
              <td>
                <button
                  onClick={() => onBook(event)}
                  disabled={event.available_seats === 0}
                  style={{ padding: '4px 10px' }}
                >
                  Book
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default EventList;
